// Buscamos el contexto del cliente (viene de la rama que se haya ejecutado)
let ctxSrc = null;
try { ctxSrc = $('♻️ Build Existing Credentials').first().json; } catch(e) {}
if (!ctxSrc) { try { ctxSrc = $('✨ Build New Credentials').first().json; } catch(e) {} }
const ctx = ctxSrc || {};

const resp = $input.first().json || {};

let text = '';
try {
  text = resp?.message?.content
      || resp?.content
      || resp?.text
      || resp?.choices?.[0]?.message?.content
      || '';
  text = String(text || '').trim();
  if (!text) console.error('🔴 AI message empty. Raw:', JSON.stringify(resp).slice(0,400));
} catch (e) {
  console.error('🔴 AI parse error:', e.message);
}

if (!text) {
  text = ctx.is_existing
    ? `Hola, ${ctx.full_name} 🙏\n\nComo lo solicitó, aquí están sus credenciales de acceso a Landmark Markets:\n\nUsuario: ${ctx.username}\nContraseña: ${ctx.password}\n\n🌐 Portal de acceso: https://www.lmtrader.net/\n\nInicie sesión cuando desee 🚀`
    : `Hola, ${ctx.full_name} 🙏\n\nBienvenido a Landmark Markets. Su cuenta de trading ya está lista ✅\n\nUsuario: ${ctx.username}\nContraseña: ${ctx.password}\n\n🌐 Portal de acceso: https://www.lmtrader.net/\n\nInicie sesión y comience su viaje de trading con un 100% de crédito de bienvenida en su primer depósito 🚀`;
}

return [{ json: {
  whatsapp_message: text,
  full_name: ctx.full_name,
  username: ctx.username,
  password: ctx.password,
  phone: ctx.phone,
  whatsapp_number: ctx.whatsapp_number || ctx.phone,
  lead_id: ctx.lead_id,
  country: ctx.country,
  is_existing: ctx.is_existing || false,
  account_id: ctx.account_id || '',
  success: true
}}];

