const d = $input.first().json;
const missing = [];
if (!d.full_name || d.full_name.length < 2) missing.push('full_name');
if (!d.phone || d.phone.length < 6) missing.push('phone');
if (missing.length > 0) {
  console.error('❌ Missing required fields:', missing.join(', '));
  throw new Error('Missing required fields for Atlantis: ' + missing.join(', '));
}
const cleanPhone = String(d.phone || '').replace(/[^0-9]/g, '');
const waPhone = String(d.whatsapp_number || d.phone || '').replace(/[^0-9]/g, '') || cleanPhone;
console.log('✅ Pre-flight OK — Phone:', cleanPhone, '| WA:', waPhone, '| Name:', d.full_name);
return [{ json: {
  lead_id: String(d.lead_id || `WA-${cleanPhone}`).trim(),
  full_name: String(d.full_name || '').trim(),
  phone: cleanPhone,
  whatsapp_number: waPhone,
  country: String(d.country || 'Venezuela').trim(),
  email: String(d.email || '').trim()
}}];

const auth = $input.first().json || {};
const status = auth.statusCode || auth.status || 0;
const headers = auth.headers || {};
const body = auth.body || auth;

console.log('🔐 Atlantis login response status:', status);
console.log('🔐 Body preview:', JSON.stringify(body).slice(0, 400));

let token = '';

if (body?.success === false) {
  const errMsg = body.message || body.errorCode || 'Unknown';
  console.error('🔴 Atlantis returned success:false →', errMsg);
  throw new Error('Atlantis login failed: ' + errMsg + ' (errorCode: ' + (body.errorCode || 'n/a') + ')');
}

if (body?.data) {
  if (typeof body.data === 'string') {
    token = body.data;
  } else if (typeof body.data === 'object') {
    token = body.data.token || body.data.access_token || body.data.accessToken || body.data.jwt || body.data.bearer || '';
  }
}

if (!token) {
  const candidates = [
    body?.token, body?.access_token, body?.accessToken, body?.jwt, body?.bearer,
    body?.dto?.token, body?.dto?.access_token,
    body?.result?.token, body?.result?.access_token,
    body?.response?.token, body?.payload?.token,
    headers?.authorization?.replace?.(/^Bearer\s+/i, ''),
    headers?.Authorization?.replace?.(/^Bearer\s+/i, ''),
    headers?.['x-auth-token'], headers?.['x-access-token']
  ];
  for (const c of candidates) {
    if (c && typeof c === 'string' && c.length > 10) { token = c; break; }
  }
}

if (!token) {
  console.error('🔴 NO TOKEN FOUND. Body:', JSON.stringify(body).slice(0, 800));
  throw new Error('Atlantis login: no token in response. Status=' + status + '. Body: ' + JSON.stringify(body).slice(0, 300));
}

if (status >= 400) {
  throw new Error('Atlantis login HTTP ' + status + ': ' + JSON.stringify(body).slice(0, 300));
}

console.log('✅ Token obtained, length:', token.length, 'preview:', token.slice(0, 25) + '...');

const lead = $('🛂 Pre-flight Check1').first().json;

const HONORIFICS = /^(mr|mrs|ms|miss|dr|sr|sra|don|sir|smt|shri)\.?$/i;
let nameParts = String(lead.full_name || '').replace(/^=/, '').trim().split(/\s+/).filter(Boolean);
while (nameParts.length > 1 && HONORIFICS.test(nameParts[0])) nameParts.shift();
const firstName = (nameParts.shift() || 'User').slice(0, 60);
const lastName  = nameParts.join(' ').slice(0, 60) || '';
const rnd = Math.floor(1000 + Math.random() * 9000);
const baseUser = firstName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '').slice(0, 12) || 'user';
const username = (baseUser + rnd).slice(0, 30);
const password = baseUser + '@' + rnd.toString().slice(0,2) + firstName.charAt(0).toUpperCase();
const phone = String(lead.phone || '').replace(/[^0-9]/g, '');
const syntheticEmail = `${username.toLowerCase()}@leads.landmarkmarkets.io`;

return [{ json: {
  bearer: token,
  lead_id: String(lead.lead_id || '').replace(/^=/, '').trim(),
  full_name: String(lead.full_name || '').replace(/^=/, '').trim(),
  phone,
  country: String(lead.country || 'India').replace(/^=/, '').trim(),
  username,
  password,
  payload: {
    accountID: -1,
    accountMirroringAccountIds: [],
    accountMirroringPolicyId: -1,
    address: '',
    currencySign: '',
    accountIdPrefix: '',
    userAgentCommissionPolicyAccountDTOS: [],
    clientPriceExecution: false,
    canTransferMoney: false,
    canTransferPosition: false,
    country: lead.country || 'India',
    currenciesPolicyID: 1,
    firstName,
    lastName,
    forceChangePassword: false,
    email: syntheticEmail,
    genericPolicyID: 2,
    ignoreLiquidation: false,
    isAllowMultiSession: false,
    isDemo: false,
    isLocked: false,
    mobile: phone,
    parentId: 8,
    password,
    secondPassword: password,
    investorPassword: password,
    percentageLevel1: 100,
    percentageLevel2: 100,
    percentageLevel3: 100,
    percentageLevel4: 100,
    creditLoanPercentage: 0,
    roboDealerPolicyId: -1,
    telephonePass: '',
    tradingType: 1,
    userCurrencyId: 1,
    userType: 1,
    username,
    validateMoneyBeforeClose: false,
    validateMoneyBeforeEntry: true,
    closeOnly: false,
    openOnly: false,
    noSellAtLoss: false,
    enableCashDelivery: false,
    enableDepositRequest: true,
    enableWithdrawalRequest: true,
    canCreateOrUpdateEntryOrder: true,
    sendCredentialsEmailToUser: false,
    blockFrequentTradesSeconds: 100,
    isVerified: true,
    ignoreBlockTradeIfInLoss: false,
    userWhiteListIps: [],
    enableApi: false,
    chargeMarginForEntry: false,
    assignAgentToMySelf: false,
    quotesOnly: false,
    pidsScriptPolicyId: 6
  }
}}];

const resp = $input.first().json || {};
const status = resp.statusCode || resp.status || 0;
const body = resp.body || resp;
const ctx = $('🧱 Build Atlantis Payload1').first().json;

console.log('👤 Atlantis create user — HTTP:', status);
console.log('👤 Response preview:', JSON.stringify(body).slice(0, 600));

const atlantisSuccess = body?.success;
const atlantisErrorCode = body?.errorCode || '';
const atlantisMessage = body?.message || '';

const respText = JSON.stringify(body).toLowerCase();
const isDuplicate = respText.includes('alreadyexists') ||
                    respText.includes('already exists') ||
                    respText.includes('duplicate') ||
                    atlantisErrorCode.toLowerCase().includes('exist') ||
                    (respText.includes('username') && respText.includes('taken'));

if (status >= 400 || atlantisSuccess === false) {
  const errorMsg = atlantisMessage ||
                   body?.error?.message ||
                   body?.errors?.[0]?.message ||
                   body?.errors?.[0] ||
                   (Array.isArray(body?.errors) ? body.errors.join('; ') : null) ||
                   JSON.stringify(body).slice(0, 300);
  console.error('🔴 Atlantis create user FAILED. HTTP', status, 'errorCode:', atlantisErrorCode, '—', errorMsg);
  return [{ json: {
    success: false,
    duplicate: isDuplicate,
    http_status: status,
    atlantis_error_code: atlantisErrorCode,
    error_message: errorMsg,
    username: ctx.username,
    phone: ctx.phone,
    full_name: ctx.full_name,
    lead_id: ctx.lead_id,
    raw_response: body
  }}];
}

const userData = body?.data || body?.dto || body || {};
const accountId = userData?.accountID || userData?.accountId || userData?.id || '';
const userId = userData?.userId || userData?.id || '';

console.log('✅ Atlantis user created. accountId:', accountId, 'userId:', userId);

return [{ json: {
  success: true,
  duplicate: false,
  http_status: status,
  account_id: accountId,
  user_id: userId,
  username: ctx.username,
  password: ctx.password,
  phone: ctx.phone,
  full_name: ctx.full_name,
  lead_id: ctx.lead_id,
  country: ctx.country,
  raw_response: body
}}];

const d = $input.first().json;
let waStatus = 0;
try { waStatus = $('📲 Send WhatsApp Credentials1').first().json?.statusCode || 0; } catch(e) {}
console.log('🎉 SUCCESS — user:', d.username, '| existing:', d.is_existing, '| account_id:', d.account_id);
return [{ json: {
  status: 'SUCCESS',
  is_existing: d.is_existing || false,
  username: d.username,
  password: d.password,
  account_id: d.account_id,
  phone: d.phone,
  full_name: d.full_name,
  lead_id: d.lead_id,
  whatsapp_status: waStatus
}}];

const d = $input.first().json;
console.error('🔴 FAILURE — lead_id:', d.lead_id, '| http:', d.http_status, '| error:', d.error_message);
return [{ json: {
  status: 'FAILURE',
  error_message: d.error_message || 'unknown',
  http_status: d.http_status,
  atlantis_error_code: d.atlantis_error_code || '',
  phone: d.phone,
  full_name: d.full_name,
  lead_id: d.lead_id,
  duplicate: d.duplicate || false
}}];

// === Universal normalizer ===
const raw = $input.first().json || {};

// CASO 0: Tool call de ElevenLabs durante la llamada
const isToolCall = (raw.body?.event === 'account_requested' || raw.body?.intent === 'OPEN_FREE_ACCOUNT' ||
                    raw.event === 'account_requested' || raw.intent === 'OPEN_FREE_ACCOUNT');
if (isToolCall) {
  const b = raw.body || raw;
  const cleanPhone = String(b.phone || '').replace(/[^0-9]/g, '');
  const waNumber = String(b.whatsapp_number || b.phone || '').replace(/[^0-9]/g, '') || cleanPhone;
  console.log('🟡 Tool call ElevenLabs | phone:', cleanPhone, '| whatsapp:', waNumber, '| name:', b.full_name);
  return [{ json: {
    source: 'elevenlabs_tool',
    lead_id: String(b.lead_id || `CALL-${cleanPhone}`).trim(),
    full_name: String(b.full_name || '').trim(),
    phone: cleanPhone,
    whatsapp_number: waNumber,
    email: cleanPhone + '@leads.landmarkmarkets.io',
    country: String(b.country || 'India').trim(),
    elevenlabs_call_id: b.conversation_id || '',
    status_raw: '',
    duration_secs: 0,
    transcript: '',
    sentiment: '',
    intent: '',
    classification: 'INTERESTED',
    callback_requested: false,
    callback_date: '',
    interested: true,
    account_opened: 'PENDING',
    conversation_summary: 'Account requested during call'
  }}];
}

// CASO 1: Sub-workflow desde WhatsApp bot
const isSubworkflow = !!(raw.phone && raw.full_name && !raw.body && !raw.data && !raw.transcript);
if (isSubworkflow) {
  console.log('🟦 Sub-workflow path (WhatsApp bot)', JSON.stringify(raw));
  const cleanPhone = String(raw.phone || '').replace(/[^0-9]/g, '');
  return [{ json: {
    source: 'subworkflow',
    lead_id: String(raw.lead_id || `WA-${cleanPhone}`).trim(),
    full_name: String(raw.full_name || '').trim(),
    phone: cleanPhone,
    country: String(raw.country || 'India').trim(),
    elevenlabs_call_id: '',
    status_raw: '',
    duration_secs: 0,
    transcript: '',
    sentiment: '',
    intent: '',
    classification: 'INTERESTED',
    callback_requested: false,
    callback_date: '',
    interested: true,
    account_opened: 'PENDING',
    conversation_summary: 'Account creation from WhatsApp bot'
  }}];
}

// CASO 2: ElevenLabs post-call webhook (código original sin cambios)
console.log('🟪 ElevenLabs webhook path');
const body = raw.body || raw;
const data = body.data || body;
const lead = (data.conversation_initiation_client_data && data.conversation_initiation_client_data.dynamic_variables) || data.dynamic_variables || {};
const transcriptArr = data.transcript || data.transcripts || [];
const transcriptText = Array.isArray(transcriptArr)
  ? transcriptArr.map(t => `${t.role || t.speaker || 'agent'}: ${t.message || t.text || ''}`).join('\n')
  : (typeof transcriptArr === 'string' ? transcriptArr : '');
const analysis = data.analysis || {};
const duration = data.metadata?.call_duration_secs || data.call_duration_secs || data.duration || 0;
const statusRaw = data.status || data.call_status || analysis.call_successful || '';
const callId = data.conversation_id || data.call_sid || data.conversationId || '';
let classification = 'NO_ANSWER';
if (statusRaw && /failed|no.?answer|busy|noanswer|no_answer/i.test(statusRaw)) {
  classification = 'NO_ANSWER';
} else if (/wrong number|galat number|गलत नंबर/i.test(transcriptText)) {
  classification = 'WRONG_NUMBER';
} else if (/do not call|dnc|mat karo|call mat/i.test(transcriptText)) {
  classification = 'DO_NOT_CALL';
} else if (/callback|baad mein|बाद में|kal call/i.test(transcriptText)) {
  classification = 'CALLBACK_REQUESTED';
} else if (/not interested|nahin chahiye|interest nahi/i.test(transcriptText)) {
  classification = 'NOT_INTERESTED';
} else if (/yes|haan|हाँ|interested|account khol|deposit|ready/i.test(transcriptText)) {
  classification = 'INTERESTED';
} else if (analysis.intent === 'interested' || analysis.outcome === 'interested') {
  classification = 'INTERESTED';
}
let fullName = lead.full_name || '';
const m = transcriptText.match(/(?:naam|name|नाम)[^a-zA-Z\u0900-\u097F]{0,8}([a-zA-Z\u0900-\u097F][a-zA-Z\u0900-\u097F .]{1,60})/i);
if (m && m[1] && !fullName) fullName = m[1].trim();
const callbackDate = classification === 'CALLBACK_REQUESTED'
  ? new Date(Date.now() + 24*60*60*1000).toISOString()
  : '';
const cleanPhone = String(lead.phone || data.to_number || '').replace(/[^0-9]/g, '');
return [{ json: {
  source: 'webhook',
  lead_id: String(lead.lead_id || data.lead_id || `EL-${callId}`).trim(),
  full_name: fullName,
  phone: cleanPhone,
  country: lead.country || 'India',
  elevenlabs_call_id: callId,
  status_raw: statusRaw,
  duration_secs: duration,
  transcript: transcriptText,
  sentiment: analysis.sentiment || '',
  intent: analysis.intent || analysis.user_intent || '',
  classification,
  callback_requested: classification === 'CALLBACK_REQUESTED',
  callback_date: callbackDate,
  interested: classification === 'INTERESTED',
  account_opened: classification === 'INTERESTED' ? 'PENDING' : '',
  conversation_summary: (analysis.transcript_summary || analysis.summary || transcriptText.slice(0, 800))
}}];
